/**
 * Icon source of truth. Every glyph the console and the marketing site draw
 * comes from a published set (Lucide for UI strokes, Simple Icons for brand
 * marks) through this manifest; nothing is hand-drawn. Run it after editing
 * the manifest or bumping either @iconify-json package, then commit the
 * generated files:
 *
 *   bun console/shared/scripts/gen-icons.mjs
 *
 * Output is the inner markup of a 24x24 viewBox so a wrapper (Icon.svelte,
 * Icon.astro) owns stroke weight, size and colour. Lucide bodies ship
 * per-path presentation attributes (stroke-width="2" etc.) which would beat
 * the wrapper's; they are stripped here so the existing CSS overrides and
 * the 1.6 weight keep working. Simple Icons are filled marks and keep
 * fill="currentColor" on the path so they render inside the stroke wrapper
 * without a fill prop.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const sets = {
  lucide: require('@iconify-json/lucide/icons.json'),
  'simple-icons': require('@iconify-json/simple-icons/icons.json')
};

// name used in code -> "set:icon"
const CONSOLE = {
  // navigation
  overview: 'lucide:layout-dashboard',
  commands: 'lucide:terminal',
  modules: 'lucide:layout-grid',
  discord: 'simple-icons:discord',
  card: 'lucide:credit-card',
  settings: 'lucide:sliders-horizontal',
  home: 'lucide:house',
  server: 'lucide:server',
  lanes: 'lucide:columns-3',
  pulse: 'lucide:activity',
  users: 'lucide:users',
  activity: 'lucide:chart-line',
  bell: 'lucide:bell',
  moderation: 'lucide:shield',
  audit: 'lucide:scroll-text',
  list: 'lucide:list',
  // icon-only controls and state marks
  x: 'lucide:x',
  trash: 'lucide:trash-2',
  edit: 'lucide:pencil',
  search: 'lucide:search',
  plus: 'lucide:plus',
  power: 'lucide:power',
  check: 'lucide:check',
  link: 'lucide:link',
  lock: 'lucide:lock',
  chevron: 'lucide:chevron-down'
};

const WEB = {
  leaf: 'lucide:leaf',
  bulb: 'lucide:lightbulb',
  copy: 'lucide:copy',
  check: 'lucide:check',
  discord: 'simple-icons:discord',
  x: 'simple-icons:x',
  tiktok: 'simple-icons:tiktok',
  youtube: 'simple-icons:youtube',
  github: 'simple-icons:github'
};

const STRIP = /\s(?:fill="none"|stroke="currentColor"|stroke-linecap="round"|stroke-linejoin="round"|stroke-width="2")/g;

function body(ref) {
  const [set, name] = ref.split(':');
  const icon = sets[set]?.icons[name];
  if (!icon) throw new Error(`gen-icons: ${ref} not found`);
  if (sets[set].width !== 24 || sets[set].height !== 24) throw new Error(`gen-icons: ${set} is not 24x24`);
  return set === 'lucide' ? icon.body.replace(STRIP, '') : icon.body.replace('<path ', '<path stroke="none" ');
}

function emit(manifest) {
  const lines = Object.entries(manifest).map(([k, ref]) => `  ${k}: '${body(ref)}', // ${ref}`);
  return [
    '// Copyright (c) 2026 Adam Ousmer. All rights reserved.',
    '// Proprietary. No license granted. See LICENSE.md.',
    '',
    '// GENERATED by console/shared/scripts/gen-icons.mjs, do not edit. Values are',
    '// the inner markup of a viewBox="0 0 24 24" SVG; the Icon wrapper draws them.',
    `// Sources: @iconify-json/lucide ${require('@iconify-json/lucide/package.json').version},`,
    `// @iconify-json/simple-icons ${require('@iconify-json/simple-icons/package.json').version}.`,
    'export const icons = {',
    ...lines,
    '} as const;',
    '',
    'export type IconName = keyof typeof icons;',
    ''
  ].join('\n');
}

const root = new URL('../../../', import.meta.url).pathname;
const targets = [
  ['console/shared/lib/icons.ts', CONSOLE],
  ['web/src/lib/icons.ts', WEB]
];
for (const [rel, manifest] of targets) {
  const path = root + rel;
  const next = emit(manifest);
  let prev = '';
  try {
    prev = readFileSync(path, 'utf8');
  } catch {}
  if (prev !== next) {
    writeFileSync(path, next);
    console.log(`wrote ${rel} (${Object.keys(manifest).length} icons)`);
  } else {
    console.log(`${rel} up to date`);
  }
}
